import pandas as pd, re, html
def norm(s):
    s=html.unescape(str(s)).replace('\\n',' ').replace('\\"','"').replace("\\'","'").lower()
    s=re.sub(r"([.!?,;:()\"'/\\\[\]{}*&%$#@~+=<>|`-])",r" \1 ",s)
    return re.sub(r"\s+"," ",s).strip()
def raw(s, lower=False, keep=False):
    t=str(s)
    if not keep: t=t.replace('\\n',' ')
    t=t.replace('\n',' ').replace('\r',' ')
    if lower: t=t.lower()
    return re.sub(r"\s+"," ",t).strip()
VAR={'norm':norm,'rawlower':lambda s: raw(s,True),'raw':lambda s: raw(s),
     'rawkeep':lambda s: raw(s,keep=True),'rawkeeplower':lambda s: raw(s,True,True)}
tr=pd.read_parquet('/app/data/train-00000-of-00001.parquet').sample(frac=1.0,random_state=0)
te=pd.read_parquet('/app/data/test-00000-of-00001.parquet')
for k,fn in VAR.items():
    with open(f'/app/valid_{k}.txt','w') as f:
        for l,t in zip(te['label'].values,te['text'].values): f.write(f"__label__{l} {fn(t)}\n")
labs=tr['label'].values; txts=tr['text'].values
with open('/app/train_aug.txt','w') as f:
    for i in range(len(labs)):
        t=txts[i]; l=labs[i]
        for k in ('norm','rawlower','raw','rawkeep'):
            f.write(f"__label__{l} {VAR[k](t)}\n")
print('ok')
EOF
